window.AUTH=window.AUTH||{};window.AUTH["14-181"]={"d":"14-181","id":"2015/14-181","n":"Gobeille v. Liberty Mutual Insurance Co.","src":["osg"],"briefs":[{"k":"united-states","label":"Brief for the United States as amicus curiae supporting petitioner","date":"2015-09-04","url":"https://www.justice.gov/osg/media/790791/dl?inline","side":"pet","src":"osg","fmt":"PDF","detail":"https://www.justice.gov/osg/brief/gobeille-v-liberty-mut-ins-co-0","n":67}],"opinion":"https://tile.loc.gov/storage-services/service/ll/usrep/usrep577/usrep577312/usrep577312.pdf","tr":true,"items":[{"t":"case","label":"Aetna Health Inc. v. Davila","cite":"542 U.S. 200","y":2004,"id":"2003/02-1845","sc":1,"sum":"The Court held that Congress intended ERISA to provide a uniform system for regulating retirement schemes and benefits. If a state law conflicts with ERISA, therefore, ERISA must be used in its place.","sumSrc":"Oyez","by":{"0":"24, 32"}},{"t":"case","label":"Alessi v. Raybestos-Manhattan, Inc.","cite":"451 U.S. 504","y":1981,"id":"1980/79-1943","sc":1,"op":1,"sum":"In two suits initiated in New Jersey state court, retired employees who had received workers' compensation awards subsequent to retirement challenged the validity of provisions in their employers' pension plans reducing a retiree's pension benefits by an amount equal to a workers' compensation award for which the retiree is eligible. These private pension plans are subject to federal regulation under the Employee …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"23"}},{"t":"case","label":"Boggs v. Boggs","cite":"520 U.S. 833","y":1997,"id":"1996/96-79","sc":1,"op":5,"sum":"The Court ruled that the Employee Retirement Income Security Act of 1974 (ERISA) preempts state community-property law allowing a non-participant spouse to transfer by a testamentary instrument an interest in undistributed pension plan benefits.","sumSrc":"Oyez","by":{"0":"30, 32"}},{"t":"case","label":"California Div. of Labor Standards Enforcement v. Dillingham Constr., N.A.","cite":"519 U.S. 316","y":1997,"id":"1996/95-789","sc":1,"op":6,"ar":2,"sum":"Authored by Justice Clarence Thomas, the Court ruled that California's prevailing wage law does not \"relate to\" employee benefit plans, and thus is not preempted by the Employee Retirement Income Security Act of 1974.","sumSrc":"Oyez","by":{"0":"passim"}},{"t":"case","label":"De Buono v. NYSA-ILA Med. & Clinical Servs. Fund","cite":"520 U.S. 806","y":1997,"id":"1996/95-1594","sc":1,"op":8,"ar":6,"sum":"Authored by Justice John Paul Stevens, the Court ruled that the Employee Retirement Income Security Act does not preclude New York from imposing a gross receipts tax on ERISA funded medical centers.","sumSrc":"Oyez","by":{"0":"17, 23, 25, 27, 35"}},{"t":"case","label":"District of Columbia v. Greater Wash. Bd. of Trade","cite":"506 U.S. 125","y":1992,"id":"1992/91-1326","sc":1,"ar":1,"sum":"Section 2(c)(2) is pre-empted by ERISA. A state law \"relate[s] to\" a covered benefit plan for § 514(a) purposes if it refers to or has a connection with such a plan, even if the law is not designed to affect the plan or the effect is only indirect. See, e. g., Ingersoll-RandCo. v. McClendon, 498 U. S. 133, 139. Section 2(c)(2) measures the required health care coverage by reference to \"the existing health insurance …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"14"}},{"t":"case","label":"Egelhoff v. Egelhoff","cite":"532 U.S. 141","y":2001,"id":"2000/99-1529","sc":1,"op":24,"ar":3,"sum":"The Court held that that the Washington statute has a \"connection with\" ERISA plans and is therefore pre-empted. \"Differing state regulations affecting an ERISA plan's 'system for processing claims and paying benefits' impose 'precisely the burden that ERISA pre-emption was intended to avoid,'\" wrote Justice Thomas.","sumSrc":"Oyez","by":{"0":"passim"}},{"t":"case","label":"English v. General Elec. Co.","cite":"496 U.S. 72","y":1990,"id":"1989/89-152","sc":1,"sum":"English's state-law claim for intentional infliction of emotional distress is not pre-empted by federal law.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"31"}},{"t":"case","label":"FMC Corp. v. Holliday","cite":"498 U.S. 52","y":1990,"id":"1990/89-1048","sc":1,"sum":"Three provisions of ERISA speak to the question of preemption: the preemption clause, the saving clause, and the deemer clause. The preemption clause establishes as an area of exclusive federal concern the subject of every state law that \"relate[s] to\" an employee benefit plan governed by ERISA.","sumSrc":"Oyez","by":{"0":"33"}},{"t":"case","label":"Fort Halifax Packing Co. v. Coyne","cite":"482 U.S. 1","y":1987,"id":"1986/86-341","sc":1,"op":2,"sum":"After appellant closed its poultry packaging and processing plant and laid off most of the employees who worked there, the Director of Maine's Bureau of Labor Standards filed suit to enforce the provisions of a state statute requiring employers, in the event of a plant closing, to provide a one-time severance payment to employees not covered by an express contract providing for severance pay. The State Superior …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"16, 23, 32"}},{"t":"case","label":"Ingersoll-Rand Co. v. McClendon","cite":"498 U.S. 133","y":1990,"id":"1990/89-1298","sc":1,"op":3,"sum":"ERISA's explicit language and its structure and purpose demonstrate a congressional intent to pre-empt a state common law claim that an employee was unlawfully discharged to prevent his attainment of benefits under an ERISA-covered plan.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"14, 15, 22"}},{"t":"case","label":"John Hancock Mut. Life Ins. Co. v. Harris Trust & Sav. Bank","cite":"510 U.S. 86","y":1993,"id":"1993/92-1074","sc":1,"op":1,"sum":"Petitioner John Hancock Mutual Life Insurance Company (Hancock) and respondent Harris Trust and Savings Bank (Harris), the current trustee of a corporation's retirement plan, are party to Group Annuity Contract No. 50 (GAC 50), an agreement of a type known as a \"participating group annuity.\" Under such a contract, the insurer commingles with its general corporate assets deposits received to secure retiree benefits, …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"15"}},{"t":"case","label":"Keystone Chapter, Associated Builders & Contrac- tors, Inc. v. Foley","cite":"37 F.3d 945","y":1994,"court":"3d Cir.","url":"https://www.courtlistener.com/c/F.3d/37/945/","by":{"0":"26"}},{"t":"case","label":"Mackey v. Lanier Collection Agency & Serv., Inc.","cite":"486 U.S. 825","y":1988,"id":"1987/86-1387","sc":1,"ar":3,"sum":"After respondent collection agency obtained money judgments against participants in an \"employee welfare benefit plan\" covered by the Employee Retirement Income Security Act of 1974 (ERISA), its request to garnish the debtors' plan benefits was granted by a Georgia trial court. The State Court of Appeals reversed, holding that Ga. Code Ann. § 18-4-22.1 (1982), barring the garnishment of \"[flunds or benefits of …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"14"}},{"t":"case","label":"Massachusetts v. Morash","cite":"490 U.S. 107","y":1989,"id":"1988/88-32","sc":1,"op":1,"sum":"The Court concluded that an employee’s unused vacation time does not constitute an employee welfare benefit plan under the Employment Retirement Income Security Act of 1974.","sumSrc":"Oyez","by":{"0":"15"}},{"t":"case","label":"Metropolitan Life Ins. Co. v. Massachusetts","cite":"471 U.S. 724","y":1985,"id":"1984/84-325","sc":1,"op":1,"sum":"A Massachusetts statute (§ 47B) requires that certain minimum mentalhealth-care benefits be provided a Massachusetts resident who is insured under a general health insurance policy or an employee health-care plan that covers hospital and surgical expenses. Appellant insurer in No. 84-325 contends that § 47B, as applied to insurance policies purchased by employee health-care plans regulated by the federal Employee …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"23, 31"}},{"t":"case","label":"New York State Conference of Blue Cross & Blue Shield Plans v. Travelers Ins. Co.","cite":"514 U.S. 645","y":1995,"id":"1994/93-1408","sc":1,"op":16,"sum":"New York's surcharge provisions do not \"relate to\" employee benefit plans within the meaning of § 514(a) and, thus, are not pre-empted.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"passim"}},{"t":"case","label":"ONEOK, Inc. v. Learjet, Inc.","cite":"135 S. Ct. 1591","y":2015,"id":"2014/13-271","sc":1,"sum":"The Court held that the Natural Gas Act does not pre-empt state law claims brought by litigants who purchased gas in retail transactions.","sumSrc":"Oyez","by":{"0":"31"}},{"t":"case","label":"Pegram v. Herdrich","cite":"530 U.S. 211","y":2000,"id":"1999/98-1949","sc":1,"sum":"The Court held that mixed treatment and eligibility decisions to delay medical treatment by sending a patient to a HMO owned facility, with adverse consequences, made by a health maintenance organization through its physician, are not fiduciary decisions under ERISA.","sumSrc":"Oyez","by":{"0":"18"}},{"t":"case","label":"Rice v. Santa Fe Elevator Corp.","cite":"331 U.S. 218","y":1947,"id":"scdb/1946-098","sc":1,"sum":"1. By the 1931 amendments to §§ 6 and 29 of the United States Warehouse Act, Congress terminated the dual system of regulation provided by the original Act and substituted an exclusive system of federal regulation of warehouses licensed under the Federal Act with reference to the subjects covered thereby, except to the extent that express exceptions in the Federal Act subject certain phases of the business to state …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"31"}},{"t":"case","label":"Shaw v. Delta Air Lines, Inc.","cite":"463 U.S. 85","y":1983,"id":"1982/81-1578","sc":1,"op":2,"sum":"New York's Human Rights Law forbids discrimination in employee benefit plans on the basis of pregnancy, and its Disability Benefits Law requires employers to pay sick-leave benefits to employees unable to work because of pregnancy. Section 514(a) of the federal Employee Retirement Income Security Act of 1974 (ERISA) provides, with enumerated exceptions, that ERISA shall supersede \"any and all state laws insofar as …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"9, 13, 20, 23, 24"}},{"t":"case","label":"Standard Oil Co. v. Agsalud","cite":"633 F.2d 760","y":1980,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.2d/633/760/","sum":"Holding preempted Hawaii reporting requirements incident to law requiring employers to provide prepaid health plan.","sumSrc":"brief:0","by":{"0":"16"}},{"t":"case","label":"UNUM Life Ins. Co. of Am. v. Ward","cite":"526 U.S. 358","y":1999,"id":"1998/97-1868","sc":1,"sum":"Delivered by Justice Ruth Bader Ginsburg, the Court held that California's agency rule is preempted by the Employee Retirement Income Security Act of 1974. Justice Ginsburg wrote for the Court that California's common-law agency rule \"would have a marked effect on plan administration,\" adding that it would force employers to take on a role for which they had not volunteered.","sumSrc":"Oyez","by":{"0":"30, 33"}},{"t":"case","label":"United States v. Locke","cite":"529 U.S. 89","y":2000,"id":"1999/98-1701","sc":1,"sum":"The Court held that Washington's regulations regarding general navigation watch procedures, crew English-language skills and training, and maritime casualty reporting are pre-empted by the comprehensive federal regulatory scheme governing oil tankers. \"The State of Washington has enacted legislation in an area where the federal interest has been manifest since the beginning of our Republic and is now well established,\" wrote Justice Kennedy for the Court.","sumSrc":"Oyez","by":{"0":"32"}},{"t":"usc","label":"29 U.S.C. § 1001","url":"https://www.law.cornell.edu/uscode/text/29/1001","subs":["(a)","(b)"],"stext":{"head":"§1001. Congressional findings and declaration of policy","paras":[[0,"(a) Benefit plans as affecting interstate commerce and the Federal taxing power"],[0,"The Congress finds that the growth in size, scope, and numbers of employee benefit plans in recent years has been rapid and substantial; that the operational scope and economic impact of such plans is increasingly interstate; that the continued well-being and security of millions of employees and their dependents are directly affected by these plans; that they are affected with a national public interest; that they have become an important factor affecting the stability of employment and the successful development of industrial relations; that they have become an important factor in commerce because of the interstate character of their activities, and of the activities of their participants, and the employers, employee organizations, and other entities by which they are established or maintained; that a large volume of the activities of such plans are carried on by means of the mails and instrumentalities of interstate commerce; that owing to the lack of employee information and adequate safeguards concerning their operation, it is desirable in the interests of employees and their beneficiaries, and to provide for the general welfare and the free flow of commerce, that disclosure be made and safeguards be provided with respect to the establishment, operation, and administration of such plans; that they substantially affect the revenues of the United States because they are afforded preferential Federal tax treatment; that despite the enormous growth in such plans many employees with long years of employment are losing anticipated retirement benefits owing to the lack of vesting provisions in such plans; that owing to the inadequacy of current minimum standards, the soundness and stability of plans with respect to adequate funds to pay promised benefits may be endangered; that owing to the termination of plans before requisite funds have been accumulated, employees and their beneficiaries have been deprived of anticipated benefits; and that it is therefore desirable in the interests of employees and their beneficiaries, for the protection of the revenue of the United States, and to provide for the free flow of commerce, that minimum standards be provided assuring the equitable character of such plans and their financial soundness."],[0,"(b) Protection of interstate commerce and beneficiaries by requiring disclosure and reporting, setting standards of conduct, etc., for fiduciaries"],[0,"It is hereby declared to be the policy of this chapter to protect interstate commerce and the interests of participants in employee benefit plans and their beneficiaries, by requiring the disclosure and reporting to participants and beneficiaries of financial and other information with respect thereto, by establishing standards of conduct, responsibility, and obligation for fiduciaries of employee benefit plans, and by providing for appropriate remedies, sanctions, and ready access to the Federal courts."],[0,"(c) Protection of interstate commerce, the Federal taxing power, and beneficiaries by vesting of accrued benefits, setting minimum standards of funding, requiring termination insurance"],[0,"It is hereby further declared to be the policy of this chapter to protect interstate commerce, the Federal taxing power, and the interests of participants in private pension plans and their beneficiaries by improving the equitable character and the soundness of such plans by requiring them to vest the accrued benefits of employees with significant periods of service, to meet minimum standards of funding, and by requiring plan termination insurance."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/29/1001?type=usc&year=mostrecent&link-type=html"},"op":3,"head":"§1001. Congressional findings and declaration of policy","tname":"Labor","by":{"0":"1, 2, 1, 1"}},{"t":"usc","label":"29 U.S.C. § 1002","url":"https://www.law.cornell.edu/uscode/text/29/1002","subs":["(1)","(13)"],"stext":{"head":"§1002. Definitions","paras":[[0,"For purposes of this subchapter:"],[0,"(1) The terms \"employee welfare benefit plan\" and \"welfare plan\" mean any plan, fund, or program which was heretofore or is hereafter established or maintained by an employer or by an employee organization, or by both, to the extent that such plan, fund, or program was established or is maintained for the purpose of providing for its participants or their beneficiaries, through the purchase of insurance or otherwise, (A) medical, surgical, or hospital care or benefits, or benefits in the event of sickness, accident, disability, death or unemployment, or vacation benefits, apprenticeship or other training programs, or day care centers, scholarship funds, or prepaid legal services, or (B) any benefit described in section 186(c) of this title (other than pensions on retirement or death, and insurance to provide such pensions)."],[0,"(2)(A) Except as provided in subparagraph (B), the terms \"employee pension benefit plan\" and \"pension plan\" mean any plan, fund, or program which was heretofore or is hereafter established or maintained by an employer or by an employee organization, or by both, to the extent that by its express terms or as a result of surrounding circumstances such plan, fund, or program—"],[1,"(i) provides retirement income to employees, or"],[1,"(ii) results in a deferral of income by employees for periods extending to the termination of covered employment or beyond,"],[0,"regardless of the method of calculating the contributions made to the plan, the method of calculating the benefits under the plan or the method of distributing benefits from the plan. A distribution from a plan, fund, or program shall not be treated as made in a form other than retirement income or as a distribution prior to termination of covered employment solely because such distribution is made to an employee who has attained age 62 and who is not separated from employment at the time of such distribution."],[0,"(B) The Secretary may by regulation prescribe rules consistent with the standards and purposes of this chapter providing one or more exempt categories under which—"],[1,"(i) severance pay arrangements, and"],[1,"(ii) supplemental retirement income payments, under which the pension benefits of retirees or their beneficiaries are supplemented to take into account some portion or all of the increases in the cost of living (as determined by the Secretary of Labor) since retirement,"],[0,"shall, for purposes of this subchapter, be treated as welfare plans rather than pension plans. In the case of any arrangement or payment a principal effect of which is the evasion of the standards or purposes of this chapter applicable to pension plans, such arrangement or payment shall be treated as a pension plan. An applicable voluntary early retirement incentive plan (as defined in section 457(e)(11)(D)(ii) of title 26) making payments or supplements described in section 457(e)(11)(D)(i) of title 26, and an applicable employment retention plan (as defined in section 457(f)(4)(C) of title 26) making payments of benefits described in section 457(f)(4)(A) of title 26, shall, for purposes of this subchapter, be treated as a welfare plan (and not a pension plan) with respect to such payments and supplements."],[0,"(C) A pooled employer plan shall be treated as—"],[1,"(i) a single employee pension benefit plan or single pension plan; and"],[1,"(ii) a plan to which section 1060(a) of this title applies."],[0,"(3) The term \"employee benefit plan\" or \"plan\" means an employee welfare benefit plan or an employee pension benefit plan or a plan which is both an employee welfare benefit plan and an employee pension benefit plan."],[0,"(4) The term \"employee organization\" means any labor union or any organization of any kind, or any agency or employee representation committee, association, group, or plan, in which employees participate and which exists for the purpose, in whole or in part, of dealing with employers concerning an employee benefit plan, or other matters incidental to employment relationships; or any employees' beneficiary association organized for the purpose in whole or in part, of establishing such a plan."],[0,"(5) The term \"employer\" means any person acting directly as an employer, or indirectly in the interest of an employer, in relation to an employee benefit plan; and includes a group or association of employers acting for an employer in such capacity."],[0,"(6) The term \"employee\" means any individual employed by an employer."],[0,"(7) The term \"participant\" means any employee or former employee of an employer, or any member or former member of an employee organization, who is or may become eligible to receive a benefit of any type from an employee benefit plan which covers employees of such employer or members of such organization, or whose beneficiaries may be eligible to receive any such benefit."],[0,"(8) The term \"beneficiary\" means a person designated by a participant, or by the terms of an employee benefit plan, who is or may become entitled to a benefit thereunder."],[0,"(9) The term \"person\" means an individual, partnership, joint venture, corporation, mutual company, joint-stock company, trust, estate, unincorporated organization, association, or employee organization."],[0,"(10) The term \"State\" includes any State of the United States, the District of Columbia, Puerto Rico, the Virgin Islands, American Samoa, Guam, Wake Island, and the Canal Zone. The term \"United States\" when used in the geographic sense means the States and the Outer Continental Shelf lands defined in the Outer Continental Shelf Lands Act (43 U.S.C. 1331–1343)."],[0,"(11) The term \"commerce\" means trade, traffic, commerce, transportation, or communication between any State and any place outside thereof."],[0,"(12) The term \"industry or activity affecting commerce\" means any activity, business, or industry in commerce or in which a labor dispute would hinder or obstruct commerce or the free flow of commerce, and includes any activity or industry \"affecting commerce\" within the meaning of the Labor Management Relations Act, 1947 [29 U.S.C. 141 et seq.], or the Railway Labor Act [45 U.S.C. 151 et seq.]."],[0,"(13) The term \"Secretary\" means the Secretary of Labor."],[0,"(14) The term \"party in interest\" means, as to an employee benefit plan—"],[1,"(A) any fiduciary (including, but not limited to, any administrator, officer, trustee, or custodian), counsel, or employee of such employee benefit plan;"],[1,"(B) a person providing services to such plan;"],[1,"(C) an employer any of whose employees are covered by such plan;"],[1,"(D) an employee organization any of whose members are covered by such plan;"],[1,"(E) an owner, direct or indirect, of 50 percent or more of—"],[2,"(i) the combined voting power of all classes of stock entitled to vote or the total value of shares of all classes of stock of a corporation.1"],[2,"(ii) the capital interest or the profits interest of a partnership, or"],[2,"(iii) the beneficial interest of a trust or unincorporated enterprise,"],[1,"which is an employer or an employee organization described in subparagraph (C) or (D);"],[1,"(F) a relative (as defined in paragraph (15)) of any individual described in subparagraph (A), (B), (C), or (E);"],[1,"(G) a corporation, partnership, or trust or estate of which (or in which) 50 percent or more of—"],[2,"(i) the combined voting power of all classes of stock entitled to vote or the total value of shares of all classes of stock of such corporation,"],[2,"(ii) the capital interest or profits interest of such partnership, or"],[2,"(iii) the beneficial interest of such trust or estate,"],[1,"is owned directly or indirectly, or held by persons described in subparagraph (A), (B), (C), (D), or (E);"],[1,"(H) an employee, officer, director (or an individual having powers or responsibilities similar to those of officers or directors), or a 10 percent or more shareholder directly or indirectly, of a person described in subparagraph (B), (C), (D), (E), or (G), or of the employee benefit plan; or"],[1,"(I) a 10 percent or more (directly or indirectly in capital or profits) partner or joint venturer of a person described in subparagraph (B), (C), (D), (E), or (G)."],[0,"The Secretary, after consultation and coordination with the Secretary of the Treasury, may by regulation prescribe a percentage lower than 50 percent for subparagraph (E) and (G) and lower than 10 percent for subparagraph (H) or (I). The Secretary may prescribe regulations for determining the ownership (direct or indirect) of profits and beneficial interests, and the manner in which indirect stockholdings are taken into account. Any person who is a party in interest with respect to a plan to which a trust described in section 501(c)(22) of title 26 is permitted to make payments under section 1403 of this title shall be treated as a party in interest with respect to such trust."],[0,"(15) The term \"relative\" means a spouse, ancestor, lineal descendant, or spouse of a lineal descendant."],[0,"(16)(A) The term \"administrator\" means—"],[1,"(i) the person specifically so designated by the terms of the instrument under which the plan is operated;"],[1,"(ii) if an administrator is not so designated, the plan sponsor; or"],[1,"(iii) in the case of a plan for which an administrator is not designated and a plan sponsor cannot be identified, such other person as the Secretary may by regulation prescribe."]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/29/1002?type=usc&year=mostrecent&link-type=html"},"op":2,"head":"§1002. Definitions","tname":"Labor","by":{"0":"1, 1"}},{"t":"usc","label":"29 U.S.C. § 1021","url":"https://www.law.cornell.edu/uscode/text/29/1021","by":{"0":"2"}},{"t":"usc","label":"29 U.S.C. § 1102","url":"https://www.law.cornell.edu/uscode/text/29/1102","subs":["(a)(1)"],"by":{"0":"2"}},{"t":"usc","label":"29 U.S.C. § 1103","url":"https://www.law.cornell.edu/uscode/text/29/1103","subs":["(a)"],"by":{"0":"2"}},{"t":"usc","label":"29 U.S.C. § 1104","url":"https://www.law.cornell.edu/uscode/text/29/1104","subs":["(a)(1)","(a)(1)(D)"],"by":{"0":"1, 1"}},{"t":"usc","label":"29 U.S.C. § 1132","url":"https://www.law.cornell.edu/uscode/text/29/1132","by":{"0":"1"}},{"t":"usc","label":"29 U.S.C. § 1134","url":"https://www.law.cornell.edu/uscode/text/29/1134","by":{"0":"3"}},{"t":"usc","label":"29 U.S.C. § 1143","url":"https://www.law.cornell.edu/uscode/text/29/1143","subs":["(a)(1)"],"by":{"0":"3, 21"}},{"t":"usc","label":"29 U.S.C. § 1144","url":"https://www.law.cornell.edu/uscode/text/29/1144","subs":["(a)","(b)(2)","(b)(2)(A)","(b)(4)","(c)(1)","(d)"],"stext":{"head":"§1144. Other laws","paras":[[0,"(a) Supersedure; effective date"],[0,"Except as provided in subsection (b) of this section, the provisions of this subchapter and subchapter III shall supersede any and all State laws insofar as they may now or hereafter relate to any employee benefit plan described in section 1003(a) of this title and not exempt under section 1003(b) of this title. This section shall take effect on January 1, 1975."],[0,"(b) Construction and application"],[0,"(1) This section shall not apply with respect to any cause of action which arose, or any act or omission which occurred, before January 1, 1975."],[0,"(2)(A) Except as provided in subparagraph (B), nothing in this subchapter shall be construed to exempt or relieve any person from any law of any State which regulates insurance, banking, or securities."],[0,"(B) Neither an employee benefit plan described in section 1003(a) of this title, which is not exempt under section 1003(b) of this title (other than a plan established primarily for the purpose of providing death benefits), nor any trust established under such a plan, shall be deemed to be an insurance company or other insurer, bank, trust company, or investment company or to be engaged in the business of insurance or banking for purposes of any law of any State purporting to regulate insurance companies, insurance contracts, banks, trust companies, or investment companies."],[0,"(3) Nothing in this section shall be construed to prohibit use by the Secretary of services or facilities of a State agency as permitted under section 1136 of this title."],[0,"(4) Subsection (a) shall not apply to any generally applicable criminal law of a State."],[0,"(5)(A) Except as provided in subparagraph (B), subsection (a) shall not apply to the Hawaii Prepaid Health Care Act (Haw. Rev. Stat. §§393–1 through 393–51)."],[0,"(B) Nothing in subparagraph (A) shall be construed to exempt from subsection (a)—"],[1,"(i) any State tax law relating to employee benefit plans, or"],[1,"(ii) any amendment of the Hawaii Prepaid Health Care Act enacted after September 2, 1974, to the extent it provides for more than the effective administration of such Act as in effect on such date."],[0,"(C) Notwithstanding subparagraph (A), parts 1 and 4 of this subtitle, and the preceding sections of this part to the extent they govern matters which are governed by the provisions of such parts 1 and 4, shall supersede the Hawaii Prepaid Health Care Act (as in effect on or after January 14, 1983), but the Secretary may enter into cooperative arrangements under this paragraph and section 1136 of this title with officials of the State of Hawaii to assist them in effectuating the policies of provisions of such Act which are superseded by such parts 1 and 4 and the preceding sections of this part."],[0,"(6)(A) Notwithstanding any other provision of this section—"],[1,"(i) in the case of an employee welfare benefit plan which is a multiple employer welfare arrangement and is fully insured (or which is a multiple employer welfare arrangement subject to an exemption under subparagraph (B)), any law of any State which regulates insurance may apply to such arrangement to the extent that such law provides—"],[2,"(I) standards, requiring the maintenance of specified levels of reserves and specified levels of contributions, which any such plan, or any trust established under such a plan, must meet in order to be considered under such law able to pay benefits in full when due, and"],[2,"(II) provisions to enforce such standards, and"],[1,"(ii) in the case of any other employee welfare benefit plan which is a multiple employer welfare arrangement, in addition to this subchapter, any law of any State which regulates insurance may apply to the extent not inconsistent with the preceding sections of this subchapter."],[0,"(B) The Secretary may, under regulations which may be prescribed by the Secretary, exempt from subparagraph (A)(ii), individually or by class, multiple employer welfare arrangements which are not fully insured. Any such exemption may be granted with respect to any arrangement or class of arrangements only if such arrangement or each arrangement which is a member of such class meets the requirements of section 1002(1) and section 1003 of this title necessary to be considered an employee welfare benefit plan to which this subchapter applies."],[0,"(C) Nothing in subparagraph (A) shall affect the manner or extent to which the provisions of this subchapter apply to an employee welfare benefit plan which is not a multiple employer welfare arrangement and which is a plan, fund, or program participating in, subscribing to, or otherwise using a multiple employer welfare arrangement to fund or administer benefits to such plan's participants and beneficiaries."],[0,"(D) For purposes of this paragraph, a multiple employer welfare arrangement shall be considered fully insured only if the terms of the arrangement provide for benefits the amount of all of which the Secretary determines are guaranteed under a contract, or policy of insurance, issued by an insurance company, insurance service, or insurance organization, qualified to conduct business in a State."],[0,"(7) Subsection (a) shall not apply to qualified domestic relations orders (within the meaning of section 1056(d)(3)(B)(i) of this title), qualified medical child support orders (within the meaning of section 1169(a)(2)(A) of this title), and the provisions of law referred to in section 1169(a)(2)(B)(ii) of this title to the extent they apply to qualified medical child support orders."],[0,"(8) Subsection (a) of this section shall not be construed to preclude any State cause of action—"],[1,"(A) with respect to which the State exercises its acquired rights under section 1169(b)(3) of this title with respect to a group health plan (as defined in section 1167(1) of this title), or"],[1,"(B) for recoupment of payment with respect to items or services pursuant to a State plan for medical assistance approved under title XIX of the Social Security Act [42 U.S.C. 1396 et seq.] which would not have been payable if such acquired rights had been executed before payment with respect to such items or services by the group health plan."],[0,"(9) For additional provisions relating to group health plans, see section 1191 of this title."],[0,"(c) Definitions"],[0,"For purposes of this section:"],[1,"(1) The term \"State law\" includes all laws, decisions, rules, regulations, or other State action having the effect of law, of any State. A law of the United States applicable only to the District of Columbia shall be treated as a State law rather than a law of the United States."],[1,"(2) The term \"State\" includes a State, any political subdivisions thereof, or any agency or instrumentality of either, which purports to regulate, directly or indirectly, the terms and conditions of employee benefit plans covered by this subchapter."],[0,"(d) Alteration, amendment, modification, invalidation, impairment, or supersedure of any law of the United States prohibited"],[0,"Nothing in this subchapter shall be construed to alter, amend, modify, invalidate, impair, or supersede any law of the United States (except as provided in sections 1031 and 1137(b) of this title) or any rule or regulation issued under any such law."],[0,"(e) Automatic contribution arrangements"],[0,"(1) Notwithstanding any other provision of this section, this subchapter shall supersede any law of a State which would directly or indirectly prohibit or restrict the inclusion in any plan of an automatic contribution arrangement. The Secretary may prescribe regulations which would establish minimum standards that such an arrangement would be required to satisfy in order for this subsection to apply in the case of such arrangement."],[0,"(2) For purposes of this subsection, the term \"automatic contribution arrangement\" means an arrangement—"],[1,"(A) under which a participant may elect to have the plan sponsor make payments as contributions under the plan on behalf of the participant, or to the participant directly in cash,"],[1,"(B) under which a participant is treated as having elected to have the plan sponsor make such contributions in an amount equal to a uniform percentage of compensation provided under the plan until the participant specifically elects not to have such contributions made (or specifically elects to have such contributions made at a different percentage), and"],[1,"(C) under which such contributions are invested in accordance with regulations prescribed by the Secretary under section 1104(c)(5) of this title."],[0,"(3)(A) The plan administrator of an automatic contribution arrangement shall, within a reasonable period before such plan year, provide to each participant to whom the arrangement applies for such plan year notice of the participant's rights and obligations under the arrangement which—"],[1,"(i) is sufficiently accurate and comprehensive to apprise the participant of such rights and obligations, and"],[1,"(ii) is written in a manner calculated to be understood by the average participant to whom the arrangement applies."],[0,"(B) A notice shall not be treated as meeting the requirements of subparagraph (A) with respect to a participant unless—"],[1,"(i) the notice includes an explanation of the participant's right under the arrangement not to have elective contributions made on the participant's behalf (or to elect to have such contributions made at a different percentage),"]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/29/1144?type=usc&year=mostrecent&link-type=html"},"op":13,"head":"§1144. Other laws","tname":"Labor","by":{"0":"3, 21, 3, 21, 3, 21, 3, 21, 3, 21, 3, 21"}},{"t":"usc","label":"29 U.S.C. § 1181-1191c","url":"https://www.law.cornell.edu/uscode/text/29/1181-1191c","by":{"0":"3, 21"}},{"t":"usc","label":"29 U.S.C. § 1185d","url":"https://www.law.cornell.edu/uscode/text/29/1185d","subs":["(a)"],"stext":{"head":"§1185d. Additional market reforms","paras":[[0,"(a) General rule"],[0,"Except as provided in subsection (b)—"],[1,"(1) the provisions of part A of title XXVII of the Public Health Service Act [42 U.S.C. 300gg et seq.] (as amended by the Patient Protection and Affordable Care Act) shall apply to group health plans, and health insurance issuers providing health insurance coverage in connection with group health plans, as if included in this subpart; and"],[1,"(2) to the extent that any provision of this part conflicts with a provision of such part A with respect to group health plans, or health insurance issuers providing health insurance coverage in connection with group health plans, the provisions of such part A shall apply."],[0,"(b) Exception"],[0,"Notwithstanding subsection (a), the provisions of sections 2716 and 2718 of title XXVII of the Public Health Service Act [42 U.S.C. 300gg–16, 300gg–18] (as amended by the Patient Protection and Affordable Care Act) shall not apply with respect to self-insured group health plans, and the provisions of this part shall continue to apply to such plans as if such sections of the Public Health Service Act (as so amended) had not been enacted."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/29/1185d?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§1185d. Additional market reforms","tname":"Labor","by":{"0":"3, 3"}},{"t":"usc","label":"29 U.S.C. § 1191","url":"https://www.law.cornell.edu/uscode/text/29/1191","subs":["(a)(2)"],"stext":{"head":"§1191. Preemption; State flexibility; construction","paras":[[0,"(a) Continued applicability of State law with respect to health insurance issuers"],[0,"(1) In general"],[1,"Subject to paragraph (2) and except as provided in subsection (b), this part shall not be construed to supersede any provision of State law which establishes, implements, or continues in effect any standard or requirement solely relating to health insurance issuers in connection with group health insurance coverage except to the extent that such standard or requirement prevents the application of a requirement of this part."],[0,"(2) Continued preemption with respect to group health plans"],[1,"Nothing in this part shall be construed to affect or modify the provisions of section 1144 of this title with respect to group health plans."],[0,"(b) Special rules in case of portability requirements"],[0,"(1) In general"],[1,"Subject to paragraph (2), the provisions of this part relating to health insurance coverage offered by a health insurance issuer supersede any provision of State law which establishes, implements, or continues in effect a standard or requirement applicable to imposition of a preexisting condition exclusion specifically governed by section 1181 of this title which differs from the standards or requirements specified in such section."],[0,"(2) Exceptions"],[1,"Only in relation to health insurance coverage offered by a health insurance issuer, the provisions of this part do not supersede any provision of State law to the extent that such provision—"],[2,"(A) substitutes for the reference to \"6-month period\" in section 1181(a)(1) of this title a reference to any shorter period of time;"],[2,"(B) substitutes for the reference to \"12 months\" and \"18 months\" in section 1181(a)(2) of this title a reference to any shorter period of time;"],[2,"(C) substitutes for the references to \"63 days\" in sections 1181(c)(2)(A) and (d)(4)(A) 1 of this title a reference to any greater number of days;"],[2,"(D) substitutes for the reference to \"30-day period\" in sections 1181(b)(2) 2 and (d)(1) of this title a reference to any greater period;"],[2,"(E) prohibits the imposition of any preexisting condition exclusion in cases not described in section 1181(d) of this title or expands the exceptions described in such section;"],[2,"(F) requires special enrollment periods in addition to those required under section 1181(f) of this title; or"],[2,"(G) reduces the maximum period permitted in an affiliation period under section 1181(g)(1)(B) 3 of this title."],[0,"(c) Rules of construction"],[0,"Except as provided in section 1185 of this title, nothing in this part shall be construed as requiring a group health plan or health insurance coverage to provide specific benefits under the terms of such plan or coverage."],[0,"(d) Definitions"],[0,"For purposes of this section—"],[0,"(1) State law"],[1,"The term \"State law\" includes all laws, decisions, rules, regulations, or other State action having the effect of law, of any State. A law of the United States applicable only to the District of Columbia shall be treated as a State law rather than a law of the United States."],[0,"(2) State"],[1,"The term \"State\" includes a State, the Northern Mariana Islands, any political subdivisions of a State or such Islands, or any agency or instrumentality of either."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/29/1191?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§1191. Preemption; State flexibility; construction","tname":"Labor","by":{"0":"3"}},{"t":"usc","label":"29 U.S.C. § 1191b","url":"https://www.law.cornell.edu/uscode/text/29/1191b","subs":["(a)"],"by":{"0":"3"}},{"t":"law","label":"Patient Protection and Affordable Care Act, Pub. L. No. 111-148","url":"https://www.govinfo.gov/link/plaw/111/public/148","by":{"0":"3"}},{"t":"usc","label":"42 U.S.C. § 1315a","url":"https://www.law.cornell.edu/uscode/text/42/1315a","subs":["(a)(1)","(b)(2)(B)","(b)(2)(B)(xi)","(b)(4)"],"by":{"0":"20, 26, 26, 26, 26"}},{"t":"usc","label":"42 U.S.C. § 1395kk","url":"https://www.law.cornell.edu/uscode/text/42/1395kk","subs":["(e)","(e)(2)(A)"],"stext":{"head":"§1395kk. Administration of insurance programs","paras":[[0,"(a) Functions of Secretary; performance directly or by contract"],[0,"Except as otherwise provided in this subchapter and in the Railroad Retirement Act of 1974 [45 U.S.C. 231 et seq.], the insurance programs established by this subchapter shall be administered by the Secretary. The Secretary may perform any of his functions under this subchapter directly, or by contract providing for payment in advance or by way of reimbursement, and in such installments, as the Secretary may deem necessary."],[0,"(b) Contracts to secure special data, actuarial information, etc."],[0,"The Secretary may contract with any person, agency, or institution to secure on a reimbursable basis such special data, actuarial information, and other information as may be necessary in the carrying out of his functions under this subchapter."],[0,"(c) Oaths and affirmations"],[0,"In the course of any hearing, investigation, or other proceeding that he is authorized to conduct under this subchapter, the Secretary may administer oaths and affirmations."],[0,"(d) Inclusion of Medicare provider and supplier payments in Federal Payment Levy Program"],[0,"(1) In general"],[1,"The Centers for Medicare & Medicaid Services shall take all necessary steps to participate in the Federal Payment Levy Program under section 6331(h) of the Internal Revenue Code of 1986 as soon as possible and shall ensure that—"],[2,"(A) at least 50 percent of all payments under parts A and B are processed through such program beginning within 1 year after July 15, 2008; 1"],[2,"(B) at least 75 percent of all payments under parts A and B are processed through such program beginning within 2 years after July 15, 2008; and"],[2,"(C) all payments under parts A and B are processed through such program beginning not later than September 30, 2011."],[0,"(2) Assistance"],[1,"The Financial Management Service and the Internal Revenue Service shall provide assistance to the Centers for Medicare & Medicaid Services to ensure that all payments described in paragraph (1) are included in the Federal Payment Levy Program by the deadlines specified in that subsection."],[0,"(e) Availability of data"],[0,"(1) In general"],[1,"Subject to paragraph (4), the Secretary shall make available to qualified entities (as defined in paragraph (2)) data described in paragraph (3) for the evaluation of the performance of providers of services and suppliers."],[0,"(2) Qualified entities"],[1,"For purposes of this subsection, the term \"qualified entity\" means a public or private entity that—"],[2,"(A) is qualified (as determined by the Secretary) to use claims data to evaluate the performance of providers of services and suppliers on measures of quality, efficiency, effectiveness, and resource use; and"],[2,"(B) agrees to meet the requirements described in paragraph (4) and meets such other requirements as the Secretary may specify, such as ensuring security of data."],[0,"(3) Data described"],[1,"The data described in this paragraph are standardized extracts (as determined by the Secretary) of claims data under parts A, B, and D for items and services furnished under such parts for one or more specified geographic areas and time periods requested by a qualified entity. Beginning July 1, 2016, if the Secretary determines appropriate, the data described in this paragraph may also include standardized extracts (as determined by the Secretary) of claims data under subchapters XIX and XXI for assistance provided under such subchapters for one or more specified geographic areas and time periods requested by a qualified entity. The Secretary shall take such actions as the Secretary deems necessary to protect the identity of individuals entitled to or enrolled for benefits under such parts or under subchapters 2 XIX or XXI."],[0,"(4) Requirements"],[0,"(A) Fee"],[2,"Data described in paragraph (3) shall be made available to a qualified entity under this subsection at a fee equal to the cost of making such data available. Any fee collected pursuant to the preceding sentence shall be deposited, for periods prior to July 1, 2016, into the Federal Supplementary Medical Insurance Trust Fund under section 1395t of this title, and, beginning July 1, 2016, into the Centers for Medicare & Medicaid Services Program Management Account."],[0,"(B) Specification of uses and methodologies"],[2,"A qualified entity requesting data under this subsection shall—"],[3,"(i) submit to the Secretary a description of the methodologies that such qualified entity will use to evaluate the performance of providers of services and suppliers using such data;"],[3,"(ii)(I) except as provided in subclause (II), if available, use standard measures, such as measures endorsed by the entity with a contract under section 1395aaa(a) of this title and measures developed pursuant to section 299b–31 of this title; or"],[3,"(II) use alternative measures if the Secretary, in consultation with appropriate stakeholders, determines that use of such alternative measures would be more valid, reliable, responsive to consumer preferences, cost-effective, or relevant to dimensions of quality and resource use not addressed by such standard measures;"],[3,"(iii) include data made available under this subsection with claims data from sources other than claims data under this subchapter in the evaluation of performance of providers of services and suppliers;"],[3,"(iv) only include information on the evaluation of performance of providers and suppliers in reports described in subparagraph (C);"],[3,"(v) make available to providers of services and suppliers, upon their request, data made available under this subsection; and"],[3,"(vi) prior to their release, submit to the Secretary the format of reports under subparagraph (C)."],[0,"(C) Reports"],[2,"Any report by a qualified entity evaluating the performance of providers of services and suppliers using data made available under this subsection shall—"],[3,"(i) include an understandable description of the measures, which shall include quality measures and the rationale for use of other measures described in subparagraph (B)(ii)(II), risk adjustment methods, physician attribution methods, other applicable methods, data specifications and limitations, and the sponsors, so that consumers, providers of services and suppliers, health plans, researchers, and other stakeholders can assess such reports;"],[3,"(ii) be made available confidentially, to any provider of services or supplier to be identified in such report, prior to the public release of such report, and provide an opportunity to appeal and correct errors;"],[3,"(iii) only include information on a provider of services or supplier in an aggregate form as determined appropriate by the Secretary; and"],[3,"(iv) except as described in clause (ii), be made available to the public."],[0,"(D) Approval and limitation of uses"],[2,"The Secretary shall not make data described in paragraph (3) available to a qualified entity unless the qualified entity agrees to release the information on the evaluation of performance of providers of services and suppliers. Such entity shall only use such data, and information derived from such evaluation, for the reports under subparagraph (C). Data released to a qualified entity under this subsection shall not be subject to discovery or admission as evidence in judicial or administrative proceedings without consent of the applicable provider of services or supplier."],[0,"(f) Requirement for the Secretary to establish policies and claims edits relating to incarcerated individuals, individuals not lawfully present, and deceased individuals"],[0,"The Secretary shall establish and maintain procedures, including procedures for using claims processing edits, updating eligibility information to improve provider accessibility, and conducting recoupment activities such as through recovery audit contractors, in order to ensure that payment is not made under this subchapter for items and services furnished to an individual who is one of the following:"],[1,"(1) An individual who is incarcerated."],[1,"(2) An individual who is not lawfully present in the United States and who is not eligible for coverage under this subchapter."],[1,"(3) A deceased individual."],[0,"(g) Requirement for enrollment data reporting"],[0,"(1) In general"],[1,"Each year (beginning with 2016), the Secretary shall submit to the Committees on Ways and Means and Energy and Commerce of the House of Representatives and the Committee on Finance of the Senate a report on Medicare enrollment data (and, in the case of part A, on data on individuals receiving benefits under such part) as of a date in such year specified by the Secretary. Such data shall be presented—"],[2,"(A) by Congressional district and State; and"],[2,"(B) in a manner that provides for such data based on—"],[3,"(i) fee-for-service enrollment (as defined in paragraph (2));"],[3,"(ii) enrollment under part C (including separate for aggregate enrollment in MA–PD plans and aggregate enrollment in MA plans that are not MA–PD plans); and"],[3,"(iii) enrollment under part D."],[0,"(2) Fee-for-service enrollment defined"],[1,"For purpose of paragraph (1)(B)(i), the term \"fee-for-service enrollment\" means aggregate enrollment (including receipt of benefits other than through enrollment) under—"],[2,"(A) part A only;"],[2,"(B) part B only; and"],[2,"(C) both part A and part B."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/42/1395kk?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§1395kk. Administration of insurance programs","tname":"The Public Health and Welfare","by":{"0":"21, 26, 26"}},{"t":"usc","label":"42 U.S.C. § 300gg","url":"https://www.law.cornell.edu/uscode/text/42/300gg","stext":{"head":"§300gg. Fair health insurance premiums","paras":[[0,"(a) 1 Prohibiting discriminatory premium rates"],[0,"(1) In general"],[1,"With respect to the premium rate charged by a health insurance issuer for health insurance coverage offered in the individual or small group market—"],[2,"(A) such rate shall vary with respect to the particular plan or coverage involved only by—"],[3,"(i) whether such plan or coverage covers an individual or family;"],[3,"(ii) rating area, as established in accordance with paragraph (2);"],[3,"(iii) age, except that such rate shall not vary by more than 3 to 1 for adults (consistent with section 300gg–6(c) of this title); and"],[3,"(iv) tobacco use, except that such rate shall not vary by more than 1.5 to 1; and"],[2,"(B) such rate shall not vary with respect to the particular plan or coverage involved by any other factor not described in subparagraph (A)."],[0,"(2) Rating area"],[0,"(A) In general"],[2,"Each State shall establish 1 or more rating areas within that State for purposes of applying the requirements of this subchapter."],[0,"(B) Secretarial review"],[2,"The Secretary shall review the rating areas established by each State under subparagraph (A) to ensure the adequacy of such areas for purposes of carrying out the requirements of this subchapter. If the Secretary determines a State's rating areas are not adequate, or that a State does not establish such areas, the Secretary may establish rating areas for that State."],[0,"(3) Permissible age bands"],[1,"The Secretary, in consultation with the National Association of Insurance Commissioners, shall define the permissible age bands for rating purposes under paragraph (1)(A)(iii)."],[0,"(4) Application of variations based on age or tobacco use"],[1,"With respect to family coverage under a group health plan or health insurance coverage, the rating variations permitted under clauses (iii) and (iv) of paragraph (1)(A) shall be applied based on the portion of the premium that is attributable to each family member covered under the plan or coverage."],[0,"(5) Special rule for large group market"],[1,"If a State permits health insurance issuers that offer coverage in the large group market in the State to offer such coverage through the State Exchange (as provided for under section 18032(f)(2)(B) of this title), the provisions of this subsection shall apply to all coverage offered in such market (other than self-insured group health plans offered in such market) in the State."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/42/300gg?type=usc&year=mostrecent&link-type=html"},"op":3,"head":"§300gg. Fair health insurance premiums","tname":"The Public Health and Welfare","by":{"0":"3"}},{"t":"usc","label":"42 U.S.C. § 300gg-15a","url":"https://www.law.cornell.edu/uscode/text/42/300gg-15a","by":{"0":"7"}},{"t":"usc","label":"42 U.S.C. § 300gg-17","url":"https://www.law.cornell.edu/uscode/text/42/300gg-17","subs":["(a)","(b)"],"by":{"0":"7, 7, 7"}},{"t":"usc","label":"42 U.S.C. § 300gg-23","url":"https://www.law.cornell.edu/uscode/text/42/300gg-23","subs":["(a)(2)"],"by":{"0":"7"}},{"t":"usc","label":"42 U.S.C. § 300gg-94","url":"https://www.law.cornell.edu/uscode/text/42/300gg-94","subs":["(c)(1)(C)"],"by":{"0":"7"}},{"t":"usc","label":"42 U.S.C. § 18031","url":"https://www.law.cornell.edu/uscode/text/42/18031","subs":["(e)(3)(A)"],"by":{"0":"26"}},{"t":"usc","label":"42 U.S.C. § 18041","url":"https://www.law.cornell.edu/uscode/text/42/18041","subs":["(d)"],"stext":{"head":"§18041. State flexibility in operation and enforcement of Exchanges and related requirements","paras":[[0,"(a) Establishment of standards"],[0,"(1) In general"],[1,"The Secretary shall, as soon as practicable after March 23, 2010, issue regulations setting standards for meeting the requirements under this title,1 and the amendments made by this title,1 with respect to—"],[2,"(A) the establishment and operation of Exchanges (including SHOP Exchanges);"],[2,"(B) the offering of qualified health plans through such Exchanges;"],[2,"(C) the establishment of the reinsurance and risk adjustment programs under part E; and"],[2,"(D) such other requirements as the Secretary determines appropriate."],[1,"The preceding sentence shall not apply to standards for requirements under subtitles A and C (and the amendments made by such subtitles) for which the Secretary issues regulations under the Public Health Service Act [42 U.S.C. 201 et seq.]."],[0,"(2) Consultation"],[1,"In issuing the regulations under paragraph (1), the Secretary shall consult with the National Association of Insurance Commissioners and its members and with health insurance issuers, consumer organizations, and such other individuals as the Secretary selects in a manner designed to ensure balanced representation among interested parties."],[0,"(b) State action"],[0,"Each State that elects, at such time and in such manner as the Secretary may prescribe, to apply the requirements described in subsection (a) shall, not later than January 1, 2014, adopt and have in effect—"],[1,"(1) the Federal standards established under subsection (a); or"],[1,"(2) a State law or regulation that the Secretary determines implements the standards within the State."],[0,"(c) Failure to establish Exchange or implement requirements"],[0,"(1) In general"],[1,"If—"],[2,"(A) a State is not an electing State under subsection (b); or"],[2,"(B) the Secretary determines, on or before January 1, 2013, that an electing State—"],[3,"(i) will not have any required Exchange operational by January 1, 2014; or"],[3,"(ii) has not taken the actions the Secretary determines necessary to implement—"],[4,"(I) the other requirements set forth in the standards under subsection (a); or"],[4,"(II) the requirements set forth in subtitles A and C and the amendments made by such subtitles;"],[1,"the Secretary shall (directly or through agreement with a not-for-profit entity) establish and operate such Exchange within the State and the Secretary shall take such actions as are necessary to implement such other requirements."],[0,"(2) Enforcement authority"],[1,"The provisions of section 2736(b) 1 of the Public Health Services 2 Act [42 U.S.C. 300gg–22(b)] shall apply to the enforcement under paragraph (1) of requirements of subsection (a)(1) (without regard to any limitation on the application of those provisions to group health plans)."],[0,"(d) No interference with State regulatory authority"],[0,"Nothing in this title 1 shall be construed to preempt any State law that does not prevent the application of the provisions of this title.1"],[0,"(e) Presumption for certain State-operated Exchanges"],[0,"(1) In general"],[1,"In the case of a State operating an Exchange before January 1, 2010, and which has insured a percentage of its population not less than the percentage of the population projected to be covered nationally after the implementation of this Act, that seeks to operate an Exchange under this section, the Secretary shall presume that such Exchange meets the standards under this section unless the Secretary determines, after completion of the process established under paragraph (2), that the Exchange does not comply with such standards."],[0,"(2) Process"],[1,"The Secretary shall establish a process to work with a State described in paragraph (1) to provide assistance necessary to assist the State's Exchange in coming into compliance with the standards for approval under this section."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/42/18041?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§18041. State flexibility in operation and enforcement of Exchanges and related requirements","tname":"The Public Health and Welfare","by":{"0":"26"}},{"t":"reg","label":"29 C.F.R. pt. 2520","url":"https://www.ecfr.gov/current/title-29/part-2520","by":{"0":"2"}}]};